INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4901029, 711266, 65234, '<td valign="top">Lighting and detail are nice; you''ve got a good range to tones here.  I see you went with a suggestion of purple instead of a depiction of it.  I get it, but I think there are images that more strongly smack me in the face with the idea of purple and are also technically strong.</td>', 'Lighting and detail are nice; you''ve got a good range to tones here.  I see you went with a suggestion of purple instead of a depiction of it.  I get it, but I think there are images that more strongly smack me in the face with the idea of purple and are also technically strong.', '2008-08-20 19:12:32.000000', NULL, 1),
(4901038, 711390, 65234, '<td valign="top">This place looks magical!</td>', 'This place looks magical!', '2008-08-20 19:16:32.000000', NULL, 1),
(4901047, 710912, 65234, '<td valign="top">Looks like the inside of the flower is a blazing inferno.  I like the lighting and the bees are a definite bonus.</td>', 'Looks like the inside of the flower is a blazing inferno.  I like the lighting and the bees are a definite bonus.', '2008-08-20 19:19:56.000000', NULL, 1),
(4901050, 712246, 65234, '<td valign="top">Really pretty scene.  Maybe a bit oversaturated?</td>', 'Really pretty scene.  Maybe a bit oversaturated?', '2008-08-20 19:21:50.000000', NULL, 1),
(4901051, 712274, 65234, '<td valign="top">I see this scene every day in the summer :-)  And I love it.  Nicely captured.</td>', 'I see this scene every day in the summer :-)  And I love it.  Nicely captured.', '2008-08-20 19:22:43.000000', NULL, 1),
(4901055, 711648, 65234, '<td valign="top">This is a great portrait and the background is wonderfully purple.</td>', 'This is a great portrait and the background is wonderfully purple.', '2008-08-20 19:23:51.000000', NULL, 1),
(4901058, 712142, 65234, '<td valign="top">A little bright, but nicely composed and quite purple.</td>', 'A little bright, but nicely composed and quite purple.', '2008-08-20 19:25:04.000000', NULL, 1),
(4901074, 711827, 90387, '<td valign="top">Excellent composition and lines. Great job! :-)</td>', 'Excellent composition and lines. Great job! :-)', '2008-08-20 19:34:37.000000', NULL, 1),
(4901081, 712318, 31341, '<td valign="top">Too much purple....doesn''t look at all natural.</td>', 'Too much purple....doesn''t look at all natural.', '2008-08-20 19:36:44.000000', NULL, 1),
(4901084, 710917, 90387, '<td valign="top">Congratulations on joining us in this crazy madcap adventure.  If you hang in for awhile, I can guarantee that it will be a rewarding one!  What I might suggest would be to make the purple object more the focal point for the photograph.  Also, you could adjust the white balace to remove the yellow hue caused by the street lights.  This in turn would make the purple sweatshirt pop!  Best of luck to you. :-)</td>', 'Congratulations on joining us in this crazy madcap adventure.  If you hang in for awhile, I can guarantee that it will be a rewarding one!  What I might suggest would be to make the purple object more the focal point for the photograph.  Also, you could adjust the white balace to remove the yellow hue caused by the street lights.  This in turn would make the purple sweatshirt pop!  Best of luck to you. :-)', '2008-08-20 19:41:30.000000', NULL, 1),
(4901092, 711852, 90387, '<td valign="top">Simple and clean...very nice.  Now was the ribbon really purple or did you adjust the color? :-)</td>', 'Simple and clean...very nice.  Now was the ribbon really purple or did you adjust the color? :-)', '2008-08-20 19:45:04.000000', NULL, 1),
(4901100, 711250, 90387, '<td valign="top">Very interesting photo you have here.  Can''t wait to read your comments at the end!  I really like the points of light and the shadows.  There seems to be quite a bit of grain, but not sure of that was avoidable or not.  I''m leaning towards not.</td>', 'Very interesting photo you have here.  Can''t wait to read your comments at the end!  I really like the points of light and the shadows.  There seems to be quite a bit of grain, but not sure of that was avoidable or not.  I''m leaning towards not.', '2008-08-20 19:48:13.000000', NULL, 1),
(4901126, 711634, 96755, '<td valign="top">Great capture.</td>', 'Great capture.', '2008-08-20 20:04:57.000000', NULL, 1),
