(4903692, 711459, 86090, '<td valign="top">i like the use of shadows and highlights, well done!</td>', 'i like the use of shadows and highlights, well done!', '2008-08-22 00:12:29.000000', NULL, 1),
(4903695, 712298, 83845, '<td valign="top">Beautifully done!   I believe that cropping out just about the people in the background would get rid of several distractions and bring focus on your stunning model.  7</td>', 'Beautifully done!   I believe that cropping out just about the people in the background would get rid of several distractions and bring focus on your stunning model.  7', '2008-08-22 00:14:58.000000', NULL, 1),
(4903697, 710917, 96881, '<td valign="top">Firstly, Congrats on Submitting.  Time to jump off the deep end, and keep submitting each week.  Don''t get turned off by low marks early, and try to keep inproving your skils.<br/>OK, the focus of the image is the front left, making everything else out of focus.  Needed a greater depth of field, and the purple needed to be in focus.<br/>Also, for a challenge like this, the photo needs to scream purple, so the person needed to be larger in the frame.<br/>Did you Post Process your image?  There are many things you are allowed to do in Basic Editing that will also improve your shot.  The colours int his are a little uninspiring, and would have been great if the Purple was a bit more vivid.  Read the Rules for what you are allowed to do, and play with photoshop/lightroom or whatever program you have.<br/>Good Luck and keep Submitting!!</td>', 'Firstly, Congrats on Submitting.  Time to jump off the deep end, and keep submitting each week.  Don''t get turned off by low marks early, and try to keep inproving your skils.OK, the focus of the image is the front left, making everything else out of focus.  Needed a greater depth of field, and the purple needed to be in focus.Also, for a challenge like this, the photo needs to scream purple, so the person needed to be larger in the frame.Did you Post Process your image?  There are many things you are allowed to do in Basic Editing that will also improve your shot.  The colours int his are a little uninspiring, and would have been great if the Purple was a bit more vivid.  Read the Rules for what you are allowed to do, and play with photoshop/lightroom or whatever program you have.Good Luck and keep Submitting!!', '2008-08-22 00:15:45.000000', NULL, 1),
(4903699, 711999, 83845, '<td valign="top">Love the depth of field, though a little soft focus on parts of the bee.</td>', 'Love the depth of field, though a little soft focus on parts of the bee.', '2008-08-22 00:16:23.000000', NULL, 1),
(4903702, 710931, 83845, '<td valign="top">Very purple.  :)  Beautiful composition.</td>', 'Very purple.  :)  Beautiful composition.', '2008-08-22 00:17:32.000000', NULL, 1),
(4903710, 712352, 83845, '<td valign="top">Very nice detail, composition and lighting.  Love the depth of field.  Great purple photo!  A good solid 9.</td>', 'Very nice detail, composition and lighting.  Love the depth of field.  Great purple photo!  A good solid 9.', '2008-08-22 00:21:08.000000', NULL, 1),
(4903716, 711497, 96881, '<td valign="top">Great Capture.<br/> <br/>Would have liked to see some Post Processing on this image, give it a little more purple and darken the image.  A darker sky and the bolt a purple colour and you would have got much hgher marks from me.</td>', 'Great Capture. Would have liked to see some Post Processing on this image, give it a little more purple and darken the image.  A darker sky and the bolt a purple colour and you would have got much hgher marks from me.', '2008-08-22 00:22:42.000000', NULL, 1),
