(4906460, 711648, 97166, '<td valign="top">I''m loving the use of color in this image.  The only knock I have for it is the seeming over-use of smoothing.  I''m pretty sure that it''s not hurting you much though.</td>', 'I''m loving the use of color in this image.  The only knock I have for it is the seeming over-use of smoothing.  I''m pretty sure that it''s not hurting you much though.', '2008-08-23 16:24:50.000000', NULL, 1),
(4906462, 712279, 97166, '<td valign="top">One of these days, I''m going to find someone willing to go through this kind of trouble to model for me.  Using pink in the frame is a nice touch, although I''m thinking, due to complementary colors, that a soft Banana Yellow might have been a really nice touch. (or even something deeper, like Yellow Ochre).</td>', 'One of these days, I''m going to find someone willing to go through this kind of trouble to model for me.  Using pink in the frame is a nice touch, although I''m thinking, due to complementary colors, that a soft Banana Yellow might have been a really nice touch. (or even something deeper, like Yellow Ochre).', '2008-08-23 16:26:09.000000', NULL, 1),
(4906463, 712158, 97166, '<td valign="top">More than the technicals, I''m loving the expression on the face. Loving it.</td>', 'More than the technicals, I''m loving the expression on the face. Loving it.', '2008-08-23 16:26:30.000000', NULL, 1),
(4906466, 710867, 97166, '<td valign="top">This is one of the few photos where the subtle use of the color is actually a benefit more than a hindrance.  The purple play with the grey-blue eyes is stunning.</td>', 'This is one of the few photos where the subtle use of the color is actually a benefit more than a hindrance.  The purple play with the grey-blue eyes is stunning.', '2008-08-23 16:27:27.000000', NULL, 1),
(4906467, 712246, 97166, '<td valign="top">While I''ve seen photos like this many, many times, I''ve yet to become bored with them.  I wish to duplicate, but lack the geography. One day. One day.</td>', 'While I''ve seen photos like this many, many times, I''ve yet to become bored with them.  I wish to duplicate, but lack the geography. One day. One day.', '2008-08-23 16:28:18.000000', NULL, 1),
(4906470, 711821, 97166, '<td valign="top">If you could be so kind, could you send me a PM (post-challenge if need be), on how you achieved this shot?  I''ve tried to shoot smoke off an incense stick many times, and have never been able to find the right combination to get it to show up so wonderfully. It always tends to disappear into my backgrounds (I''ve tried to use both black poster-board and velvet backdrops).<br/> <br/>Must be something to do with light positioning, but damned if I can figure it out.</td>', 'If you could be so kind, could you send me a PM (post-challenge if need be), on how you achieved this shot?  I''ve tried to shoot smoke off an incense stick many times, and have never been able to find the right combination to get it to show up so wonderfully. It always tends to disappear into my backgrounds (I''ve tried to use both black poster-board and velvet backdrops). Must be something to do with light positioning, but damned if I can figure it out.', '2008-08-23 16:29:52.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4906475, 710673, 97166, '<td valign="top">At first glance, it is a flower. Then, suddenly, it''s a worm-hole in the vastness of deep space, the Good Ship Stamen bursting from within, the Cruiser Pollen I in escort.<br/> <br/>Crop the top 1/5th, give it a widescreen aspect (with black bar border), and it''s a print worthy photo I''d want on my wall.</td>', 'At first glance, it is a flower. Then, suddenly, it''s a worm-hole in the vastness of deep space, the Good Ship Stamen bursting from within, the Cruiser Pollen I in escort. Crop the top 1/5th, give it a widescreen aspect (with black bar border), and it''s a print worthy photo I''d want on my wall.', '2008-08-23 16:32:04.000000', NULL, 1),
(4906518, 711426, 61961, '<td valign="top">I''d prefer not to see your purple tool. <br/> <br/>Anyway, this is good for a chuckle, but I don''t really like the sepia/color combo.  Lighting is a bit harsh.  I also notice the bottom edges of the duster aren''t colored in -- I''m sure it was a difficult PP job but nevertheless it''s kind of sloppy.</td>', 'I''d prefer not to see your purple tool.  Anyway, this is good for a chuckle, but I don''t really like the sepia/color combo.  Lighting is a bit harsh.  I also notice the bottom edges of the duster aren''t colored in -- I''m sure it was a difficult PP job but nevertheless it''s kind of sloppy.', '2008-08-23 17:09:37.000000', NULL, 1),
(4906527, 711266, 61396, '<td valign="top">That''s a good one (not voting though)</td>', 'That''s a good one (not voting though)', '2008-08-23 17:35:02.000000', NULL, 1),
