(4907382, 710771, 7743, '<td valign="top">The background feels like a painting and the colours are wonderful however the butterfly is a bit too central.</td>', 'The background feels like a painting and the colours are wonderful however the butterfly is a bit too central.', '2008-08-24 09:27:03.000000', NULL, 1),
(4907404, 712237, 8005, '<td valign="top">I like the glow.</td>', 'I like the glow.', '2008-08-24 10:26:10.000000', NULL, 1),
