(4907463, 712279, 8005, '<td valign="top">Thanks for trying something different. If I see another flower, I''m going to barf. I like the artistic setup.</td>', 'Thanks for trying something different. If I see another flower, I''m going to barf. I like the artistic setup.', '2008-08-24 10:58:33.000000', NULL, 1),
(4907557, 712170, 60047, '<td valign="top">Simply a great sky done well.</td>', 'Simply a great sky done well.', '2008-08-24 12:07:45.000000', NULL, 1),
(4907558, 712301, 60047, '<td valign="top">What an interesting look on her face!</td>', 'What an interesting look on her face!', '2008-08-24 12:07:47.000000', NULL, 1),
(4907559, 711337, 60047, '<td valign="top">Wonderfully gratuitous!</td>', 'Wonderfully gratuitous!', '2008-08-24 12:07:50.000000', NULL, 1),
(4907560, 710771, 60047, '<td valign="top">Nice colors. That bloom below the butterfly is a bit annoying due to being out of the DOF and so close to the butterfly.</td>', 'Nice colors. That bloom below the butterfly is a bit annoying due to being out of the DOF and so close to the butterfly.', '2008-08-24 12:09:20.000000', NULL, 1),
(4907563, 710783, 60047, '<td valign="top">What a fascinating answer to this challenge. Very "out-of-the-box" thinking going on here. I love the use of the black BG with the subjects.</td>', 'What a fascinating answer to this challenge. Very "out-of-the-box" thinking going on here. I love the use of the black BG with the subjects.', '2008-08-24 12:11:00.000000', NULL, 1),
(4907564, 711654, 60047, '<td valign="top">I like the purple in this, but I seem to want a better focal point than the water pattern. Perhaps this is just me?</td>', 'I like the purple in this, but I seem to want a better focal point than the water pattern. Perhaps this is just me?', '2008-08-24 12:12:14.000000', NULL, 1),
(4907566, 712179, 60047, '<td valign="top">This is a clever shot. I would have preferred a sharper silhouette, though.</td>', 'This is a clever shot. I would have preferred a sharper silhouette, though.', '2008-08-24 12:13:16.000000', NULL, 1),
(4907568, 710862, 60047, '<td valign="top">I really like how this shot answers the challenge and is so unusual. I hope you tell us how you did this.</td>', 'I really like how this shot answers the challenge and is so unusual. I hope you tell us how you did this.', '2008-08-24 12:14:05.000000', NULL, 1),
(4907573, 711250, 60047, '<td valign="top">When I first looked at this image I didn''t see the most fascinating part. I first saw the glass balls in a pattern on a purple BG. Upon the second viewing I noticed the fabulous combination of shadow and hot spots to the left of each ball. I think this photo could be a ten if you found a way to really make the shadow of the balls the focus of the shot - via a different pattern, perhaps?</td>', 'When I first looked at this image I didn''t see the most fascinating part. I first saw the glass balls in a pattern on a purple BG. Upon the second viewing I noticed the fabulous combination of shadow and hot spots to the left of each ball. I think this photo could be a ten if you found a way to really make the shadow of the balls the focus of the shot - via a different pattern, perhaps?', '2008-08-24 12:18:46.000000', NULL, 1),
(4907574, 712250, 60047, '<td valign="top">Wonderfully subtle.</td>', 'Wonderfully subtle.', '2008-08-24 12:19:01.000000', NULL, 1),
(4907578, 712219, 60047, '<td valign="top">I like how the darker mottled BG enhances the colors of the flowers.</td>', 'I like how the darker mottled BG enhances the colors of the flowers.', '2008-08-24 12:20:40.000000', NULL, 1),
(4907581, 711796, 60047, '<td valign="top">A nice avant-garde approach to this challenge. Nice geometrics.</td>', 'A nice avant-garde approach to this challenge. Nice geometrics.', '2008-08-24 12:22:54.000000', NULL, 1),
(4907582, 712088, 60047, '<td valign="top">Nice unusual flower. It could have been real easy to blow out the whites. You didn''t and this works well.</td>', 'Nice unusual flower. It could have been real easy to blow out the whites. You didn''t and this works well.', '2008-08-24 12:23:40.000000', NULL, 1),
(4907584, 711835, 60047, '<td valign="top">This is a really well done shot of a bloom. You''ve hit the DOF well.</td>', 'This is a really well done shot of a bloom. You''ve hit the DOF well.', '2008-08-24 12:25:04.000000', NULL, 1),
(4907586, 712225, 24896, '<td valign="top">Love all the frosty trees...Great IR image..Best for Luck.Scott</td>', 'Love all the frosty trees...Great IR image..Best for Luck.Scott', '2008-08-24 12:25:58.000000', NULL, 1),
(4907589, 711433, 60047, '<td valign="top">Slightly too high key for me. I like the model''s pose and expression - unique and interesting.</td>', 'Slightly too high key for me. I like the model''s pose and expression - unique and interesting.', '2008-08-24 12:26:48.000000', NULL, 1),
(4907590, 712186, 24896, '<td valign="top">Awesome!!! 10 Best of luck. Scott</td>', 'Awesome!!! 10 Best of luck. Scott', '2008-08-24 12:28:02.000000', NULL, 1),
(4907785, 712247, 71550, '<td valign="top">Nice freeze. Looks sort of like an IreneM shot.</td>', 'Nice freeze. Looks sort of like an IreneM shot.', '2008-08-24 14:31:54.000000', NULL, 1),
(4907806, 712213, 61651, '<td valign="top">Love the humor and presentation - especially in your attention to detail with the DOF and pose of the Woody.  I hope voters appreciate how this was not an easy shot to capture.</td>', 'Love the humor and presentation - especially in your attention to detail with the DOF and pose of the Woody.  I hope voters appreciate how this was not an easy shot to capture.', '2008-08-24 15:00:28.000000', NULL, 1);
