(4908478, 711901, 60047, '<td valign="top">I really got a kick out of this one. The title matches the expression wonderfully.</td>', 'I really got a kick out of this one. The title matches the expression wonderfully.', '2008-08-25 00:21:14.000000', NULL, 1),
(4908482, 712303, 60047, '<td valign="top">Almost too symmetrical. Definitely meets the challenge - but I yearn for something to break up the simplicity of the composition.</td>', 'Almost too symmetrical. Definitely meets the challenge - but I yearn for something to break up the simplicity of the composition.', '2008-08-25 00:24:15.000000', NULL, 1),
